package com.gpmachine;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GpMachinePlugin.CONFIG_GROUP)
public interface GpMachineConfig extends Config
{
	@ConfigItem(
		keyName = "enabled",
		name = "Send GE offers",
		description = "Send your Grand Exchange offers to your GP MACHINE dashboard",
		warning = "This sends your Grand Exchange offers (item, price, quantity, status) and an anonymous account id "
			+ "to the GP MACHINE server. Nothing else is sent. Continue?",
		position = 1
	)
	default boolean enabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "key",
		name = "Key",
		description = "Your personal key, made on the Plugin page of the GP MACHINE dashboard",
		secret = true,
		position = 2
	)
	default String key()
	{
		return "";
	}

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server",
		description = "Address of the GP MACHINE server",
		position = 3
	)
	default String serverUrl()
	{
		return "https://gp.217-160-143-251.sslip.io/api/v1/ge";
	}
}

package com.gpmachine;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Sends the player's own Grand Exchange offers to the GP MACHINE dashboard.
 * Read only: it listens to offer updates and never acts in the game.
 */
@Slf4j
@PluginDescriptor(
	name = "GP MACHINE",
	description = "Sends your Grand Exchange offers to your GP MACHINE flipping dashboard",
	tags = {"grand exchange", "ge", "flipping", "trade"}
)
public class GpMachinePlugin extends Plugin
{
	static final String CONFIG_GROUP = "gpmachine";
	private static final long SEND_DELAY_MS = 2000;

	@Inject
	private Client client;

	@Inject
	private GpMachineConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	private final Map<Integer, Map<String, Object>> pending = new ConcurrentHashMap<>();
	private volatile String account;
	private volatile boolean sendScheduled;

	@Provides
	GpMachineConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GpMachineConfig.class);
	}

	@Override
	protected void shutDown()
	{
		pending.clear();
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (!config.enabled() || config.key().trim().isEmpty() || client.getAccountHash() == -1)
		{
			return;
		}
		GrandExchangeOffer offer = event.getOffer();
		GrandExchangeOfferState state = offer.getState();
		if (state == GrandExchangeOfferState.EMPTY)
		{
			// RuneLite also reports empty slots while logging in: ignore them, the slot keeps its offer id
			return;
		}
		int slot = event.getSlot();
		boolean buy = state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
		boolean complete = state != GrandExchangeOfferState.BUYING && state != GrandExchangeOfferState.SELLING;
		long now = System.currentTimeMillis();

		String key = "slot" + slot;
		OfferTracker.Result id = OfferTracker.identify(slot, offer.getItemId(), offer.getPrice(), offer.getTotalQuantity(),
			buy, offer.getQuantitySold(), complete, configManager.getRSProfileConfiguration(CONFIG_GROUP, key), now);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, key, id.stored);

		account = anonymousId(client.getAccountHash());
		pending.put(slot, OfferSender.offer(id.offerId, slot, offer.getItemId(), buy, offer.getPrice(),
			offer.getTotalQuantity(), offer.getQuantitySold(), offer.getSpent(), state.name(), client.getWorld(),
			id.started, now));

		if (!sendScheduled)
		{
			// wait a moment, so the offers of one login or one tick go together in one message
			sendScheduled = true;
			executor.schedule(this::send, SEND_DELAY_MS, TimeUnit.MILLISECONDS);
		}
	}

	private void send()
	{
		sendScheduled = false;
		List<Map<String, Object>> offers = new ArrayList<>();
		for (Integer slot : new ArrayList<>(pending.keySet()))
		{
			Map<String, Object> o = pending.remove(slot);
			if (o != null)
			{
				offers.add(o);
			}
		}
		if (offers.isEmpty() || account == null)
		{
			return;
		}
		Request request;
		try
		{
			request = OfferSender.request(gson, config.serverUrl(), config.key(), account, offers);
		}
		catch (IllegalArgumentException e)
		{
			log.warn("GP MACHINE: invalid server address");
			return;
		}
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("GP MACHINE: sending failed, will retry with the next update", e);
				for (Map<String, Object> o : offers)
				{
					pending.putIfAbsent((Integer) o.get("slot"), o);
				}
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.warn("GP MACHINE: server answered {}", r.code());
					}
				}
			}
		});
	}

	/**
	 * An anonymous id for the account: a hash of RuneLite's account hash. The player's name is never sent.
	 */
	static String anonymousId(long accountHash)
	{
		try
		{
			MessageDigest sha = MessageDigest.getInstance("SHA-256");
			byte[] digest = sha.digest(Long.toString(accountHash).getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder();
			for (int i = 0; i < 8; i++)
			{
				hex.append(String.format("%02x", digest[i]));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			return Long.toHexString(accountHash);
		}
	}
}

package com.gpmachine;

import com.google.gson.Gson;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import okhttp3.MediaType;
import okhttp3.Request;
import okhttp3.RequestBody;

/**
 * Builds the message the plugin sends to the GP MACHINE server.
 */
final class OfferSender
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private OfferSender()
	{
	}

	/**
	 * One offer as it is sent. Price and spent are in gp, times in milliseconds.
	 */
	static Map<String, Object> offer(String offerId, int slot, int itemId, boolean buy, long price, int total,
		int filled, long spent, String state, int world, long started, long updated)
	{
		Map<String, Object> o = new LinkedHashMap<>();
		o.put("offer_id", offerId);
		o.put("slot", slot);
		o.put("item_id", itemId);
		o.put("buy", buy);
		o.put("price", price);
		o.put("total", total);
		o.put("filled", filled);
		o.put("spent", spent);
		o.put("state", state);
		o.put("world", world);
		o.put("started", started);
		o.put("updated", updated);
		return o;
	}

	/**
	 * @throws IllegalArgumentException when the server address is not a valid http(s) address
	 */
	static Request request(Gson gson, String url, String key, String account, List<Map<String, Object>> offers)
	{
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("account", account);
		body.put("offers", offers);
		return new Request.Builder()
			.url(url.trim())
			.header("Authorization", "Bearer " + key.trim())
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
	}
}

package com.gpmachine;

/**
 * Gives every Grand Exchange offer a stable id, also across logins.
 * RuneLite reports offers per slot; an offer is identified by its slot and the moment it was first seen.
 * The state per slot is kept as a small string, so it can be stored in the RuneLite profile config.
 */
final class OfferTracker
{
	private OfferTracker()
	{
	}

	static final class Result
	{
		final String offerId;
		final long started;
		final String stored;

		Result(String offerId, long started, String stored)
		{
			this.offerId = offerId;
			this.started = started;
			this.stored = stored;
		}
	}

	/**
	 * @param stored  what was stored for this slot before ("item:price:total:buy:started:filled:complete"), or null
	 * @param now     current time in milliseconds
	 * @return the id of this offer and the new value to store for the slot
	 */
	static Result identify(int slot, int itemId, long price, int total, boolean buy, int filled, boolean complete,
		String stored, long now)
	{
		long started = now;
		if (stored != null)
		{
			String[] p = stored.split(":");
			if (p.length == 7)
			{
				try
				{
					boolean same = Integer.parseInt(p[0]) == itemId
						&& Long.parseLong(p[1]) == price
						&& Integer.parseInt(p[2]) == total
						&& Boolean.parseBoolean(p[3]) == buy;
					int filledBefore = Integer.parseInt(p[5]);
					boolean completeBefore = Boolean.parseBoolean(p[6]);
					// a new offer with the same item, price and quantity: the old one was finished, or less is filled now
					boolean newOffer = !same || (completeBefore && !complete) || filled < filledBefore;
					if (!newOffer)
					{
						started = Long.parseLong(p[4]);
					}
				}
				catch (NumberFormatException e)
				{
					// unreadable: treat as a new offer
				}
			}
		}
		String value = itemId + ":" + price + ":" + total + ":" + buy + ":" + started + ":" + filled + ":" + complete;
		return new Result(slot + "-" + started, started, value);
	}
}

package com.gpmachine;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Starts RuneLite with this plugin loaded, for testing on your own computer.
 */
public class GpMachinePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GpMachinePlugin.class);
		RuneLite.main(args);
	}
}

package com.gpmachine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import org.junit.Test;

public class OfferTrackerTest
{
	@Test
	public void sameOfferKeepsItsIdAcrossUpdatesAndLogins()
	{
		OfferTracker.Result first = OfferTracker.identify(3, 2, 191, 1000, true, 0, false, null, 1000L);
		OfferTracker.Result later = OfferTracker.identify(3, 2, 191, 1000, true, 400, false, first.stored, 5000L);
		OfferTracker.Result done = OfferTracker.identify(3, 2, 191, 1000, true, 1000, true, later.stored, 9000L);
		assertEquals("3-1000", first.offerId);
		assertEquals(first.offerId, later.offerId);
		assertEquals(first.offerId, done.offerId);
		// after a new login RuneLite reports the same finished offer again: still the same id
		assertEquals(first.offerId, OfferTracker.identify(3, 2, 191, 1000, true, 1000, true, done.stored, 20000L).offerId);
	}

	@Test
	public void identicalNewOfferAfterTheOldOneFinishedGetsANewId()
	{
		OfferTracker.Result done = OfferTracker.identify(0, 2, 191, 1000, true, 1000, true, null, 1000L);
		OfferTracker.Result again = OfferTracker.identify(0, 2, 191, 1000, true, 0, false, done.stored, 50000L);
		assertNotEquals(done.offerId, again.offerId);
		assertEquals("0-50000", again.offerId);
	}

	@Test
	public void otherItemOrUnreadableStateIsANewOffer()
	{
		OfferTracker.Result a = OfferTracker.identify(1, 2, 191, 1000, true, 10, false, null, 1000L);
		assertNotEquals(a.offerId, OfferTracker.identify(1, 4151, 191, 1000, true, 0, false, a.stored, 2000L).offerId);
		assertEquals("1-3000", OfferTracker.identify(1, 2, 191, 1000, true, 0, false, "rubbish", 3000L).offerId);
	}

	@Test
	public void anonymousIdHidesTheAccountHash()
	{
		String id = GpMachinePlugin.anonymousId(123456789L);
		assertEquals(16, id.length());
		assertEquals(id, GpMachinePlugin.anonymousId(123456789L));
		assertNotEquals(id, GpMachinePlugin.anonymousId(987654321L));
	}
}

package com.gpmachine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Map;
import okhttp3.OkHttpClient;
import okhttp3.Response;
import org.junit.Test;

/**
 * Sends a test offer to a real GP MACHINE server, exactly as the plugin does.
 * Only runs when GPM_TEST_URL and GPM_TEST_KEY are set (a test key, not a player's key).
 */
public class ServerTest
{
	@Test
	public void serverAcceptsOffersFromThePlugin() throws Exception
	{
		String url = System.getenv("GPM_TEST_URL");
		String key = System.getenv("GPM_TEST_KEY");
		assumeTrue(url != null && key != null);
		Gson gson = new Gson();
		OkHttpClient http = new OkHttpClient();
		long now = System.currentTimeMillis();

		OfferTracker.Result id = OfferTracker.identify(2, 2, 191L, 1000, true, 1000, true, null, now);
		Map<String, Object> bought = OfferSender.offer(id.offerId, 2, 2, true, 191L, 1000, 1000, 191_000L, "BOUGHT", 302,
			id.started, now);
		Map<String, Object> selling = OfferSender.offer("5-" + now, 5, 2, false, 199L, 1000, 250, 49_750L, "SELLING", 302,
			now, now);

		try (Response r = http.newCall(OfferSender.request(gson, url, key, GpMachinePlugin.anonymousId(42L),
			Arrays.asList(bought, selling))).execute())
		{
			assertEquals(200, r.code());
			String body = r.body().string();
			assertTrue(body, body.contains("\"saved\": 2"));
		}
		try (Response r = http.newCall(OfferSender.request(gson, url, "gpm_wrong", "x", Arrays.asList(bought))).execute())
		{
			assertEquals(401, r.code());
		}
	}
}
